#!/usr/bin/env python3
"""Generate _headers (Cloudflare Pages response headers) for the site.

The Content-Security-Policy allows each page's inline <style> and <script>
blocks by SHA-256 hash, so any edit to one of those blocks changes the hash.
Run this after editing a page:

    python3 .github/scripts/build_headers.py          # rewrite _headers
    python3 .github/scripts/build_headers.py --check  # CI: fail if stale
"""
import base64
import hashlib
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
INLINE = re.compile(r"<(script|style)(\s[^>]*)?>(.*?)</\1>", re.S | re.I)


def inline_hashes():
    hashes = {"script": set(), "style": set()}
    for page in sorted(ROOT.glob("*.html")):
        for tag, attrs, body in INLINE.findall(page.read_text(encoding="utf-8")):
            if tag.lower() == "script" and attrs and "src=" in attrs:
                continue
            digest = hashlib.sha256(body.encode("utf-8")).digest()
            hashes[tag.lower()].add("'sha256-%s'" % base64.b64encode(digest).decode())
        if re.search(r"\sstyle\s*=", page.read_text(encoding="utf-8"), re.I):
            sys.exit("%s has a style= attribute; the CSP blocks those. Use a class." % page.name)
    return {k: " ".join(sorted(v)) for k, v in hashes.items()}


def render():
    h = inline_hashes()
    csp = "; ".join([
        "default-src 'none'",
        "script-src " + (h["script"] or "'none'"),
        "style-src " + (h["style"] or "'none'"),
        # The PostYourStartup badge in the index.html footer.
        "img-src 'self' https://postyourstartup.co",
        "manifest-src 'self'",
        # The iPhone waitlist form posts to FormSubmit (fetch, plus the no-JS fallback).
        # thanks.html reads the buyer's license key from api.inboxocd.com.
        "connect-src https://formsubmit.co https://api.inboxocd.com",
        "form-action https://formsubmit.co",
        "base-uri 'none'",
        "object-src 'none'",
        "frame-ancestors 'none'",
        "upgrade-insecure-requests",
    ])
    return "\n".join([
        "# Generated by .github/scripts/build_headers.py; do not edit by hand.",
        "/*",
        "  Strict-Transport-Security: max-age=31536000; includeSubDomains",
        "  Content-Security-Policy: " + csp,
        "  X-Frame-Options: DENY",
        "  X-Content-Type-Options: nosniff",
        "  Referrer-Policy: strict-origin-when-cross-origin",
        "  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=()",
        "  Cross-Origin-Opener-Policy: same-origin",
        "  Cross-Origin-Embedder-Policy: require-corp",
        "  Cross-Origin-Resource-Policy: same-origin",
        "  ! Access-Control-Allow-Origin",
        "",
        "/robots.txt",
        "  Content-Type: text/plain; charset=utf-8",
        "",
        "/sitemap.xml",
        "  Content-Type: application/xml; charset=utf-8",
        "",
    ])


def main():
    out = ROOT / "_headers"
    text = render()
    if "--check" in sys.argv:
        if not out.exists() or out.read_text(encoding="utf-8") != text:
            sys.exit("_headers is out of date: run python3 .github/scripts/build_headers.py")
        print("_headers is up to date")
        return
    out.write_text(text, encoding="utf-8")
    print("wrote", out)


if __name__ == "__main__":
    main()
